        "Loaded, şarj etmek veya yüklemek için kullanılan küçük harfli bir fiildir.",
        "Der Laden genellikle günlük yaşamda küçük bir mağazaya atıfta bulunur (im Laden einkaufen = mağazadan alışveriş yapmak).",
